const [isSaving, setIsSaving] = useState(false);
const [pdfPagesBase64, setPdfPagesBase64] = useState<string[]>([]);
const [isManualMode, setIsManualMode] = useState(false);

// Modal states
const [selectedNota, setSelectedNota] = useState(null);
const [isDetailsModalOpen, setIsDetailsModalOpen] = useState(false);
const [isEditModalOpen, setIsEditModalOpen] = useState(false);
const [isReportsModalOpen, setIsReportsModalOpen] = useState(false);
const [deletingId, setDeletingId] = useState(null);
const [isPhotoModalOpen, setIsPhotoModalOpen] = useState(false);
const [selectedPhoto, setSelectedPhoto] = useState<string | null>(null);
const [imageLoading, setImageLoading] = useState(false);
const [imageError, setImageError] = useState(false);
const [isAnalyticsView, setIsAnalyticsView] = useState(false);
const [isTransferView, setIsTransferView] = useState(false);
const [activeTab, setActiveTab] = useState<"notas" | "fornecedores">("notas");
const [paymentStatusByNotaId, setPaymentStatusByNotaId] = useState<Record<number, { status: string | null; data_pagamento: string | null }>>({});
const { selectedStore, stores } = useStore();
const { canSelectStoreNF } = usePermissions();
const [ocrLojaSelecionadaId, setOcrLojaSelecionadaId] = useState<number | null>(null);
const [ocrFormaPagamento, setOcrFormaPagamento] = useState<string>('boleto');
const [ocrCreditCardId, setOcrCreditCardId] = useState<number | null>(null);
const [availableCreditCards, setAvailableCreditCards] = useState<{ id: number; nome: string; bandeira: string; ultimos_digitos?: string }[]>([]);

// Integração MIA — registrar ações de notas fiscais
useMiaNotasFiscaisActions({
  setSearchTerm,
  setStatusFilter,
  setDateFilterStart: (v: string) => {
    setDateFilterRange(prev => ({
      from: v ? new Date(v + 'T12:00:00') : undefined,
      to: prev?.to,
    }));
  },
  setDateFilterEnd: (v: string) => {
    setDateFilterRange(prev => ({
      from: prev?.from,
      to: v ? new Date(v + 'T12:00:00') : undefined,
    }));
  },
  setDateFilterType,
  setSortAsc,
  setIsAnalyticsView,
  setIsUploadOpen,
  setSelectedNota,
  setIsDetailsModalOpen,
  setIsEditModalOpen,
  setIsReportsModalOpen,
  notas,
});

// Telemetria de busca
const { trackSearch } = useSearchTelemetry('notas-fiscais');
const telemetryAttrs = useTelemetryAttrs();
useEffect(() => {
  trackSearch(searchTerm, notas.length);
}, [searchTerm, notas.length, trackSearch]);

// Resumo: total de notas e soma dos valores
const totalNotas = notas.length;
const totalValorNotas = notas.reduce((sum, n: any) => sum + parseFloat(String(n?.valor_total || 0)), 0);

// Formatar data em dd-MM-yyyy
const formatDateBRDash = (value: any) => {
  if (!value) return '—';
  // YYYY-MM-DD vem do Postgres como string; força meio-dia local pra evitar shift de UTC
  const iso = typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value)
    ? `${value}T12:00:00`
    : value;
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '—';
  const day = String(d.getDate()).padStart(2, '0');
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const year = d.getFullYear();
  return `${day}-${month}-${year}`;
};

useEffect(() => {
  loadNotas();
}, []);

// Recupera captura pendente se a PWA recarregou após o Android matar o
// WebView durante a câmera. A captura é persistida pelo DragDropUploadArea
// em localStorage (sobrevive ao process death — sessionStorage não sobrevive).
// Tem TTL embutido, então só recupera se foi feita há pouco.
useEffect(() => {
  const pending = loadPendingCapture();
  if (pending) {
    setSelectedFile(pending.file);
    setSelectedFiles([pending.file]);
    setIsUploadOpen(true);
    toast.success('Foto recuperada — toque em Processar para continuar.');
    // Consome a captura: a foto agora vive no state da página; não queremos
    // que um próximo reload restaure de novo.
    clearPendingCapture();
  }
}, []);

// Fetch all active credit cards (qualquer cartão pode ser usado em qualquer loja)
useEffect(() => {
  const fetchCreditCards = async () => {
    const { data } = await supabase
      .from('credit_cards')
      .select('id, nome, bandeira, ultimos_digitos, loja_id')
      .eq('ativo', true)
      .order('nome');
    setAvailableCreditCards((data || []) as any[]);
  };
  fetchCreditCards();
}, []);

const loadNotas = async () => {
  const startTime = performance.now();
  try {
    const resultCount = await withTrace('financeiro.nf.lista.carregar', async () => {
      let query = supabase
        .from('notas_fiscais')
        .select('*, itens_nota_fiscal(id, nome_produto, categoria, subtotal, quantidade, valor_unitario)')
        // Excluir notas de transferência interna — pertencem à aba Transferências
        .not('fornecedor', 'ilike', '%momma doces%');

      if (searchTerm) {
        // Busca combinada por fornecedor ou número da nota
        query = query.or(`fornecedor.ilike.%${searchTerm}%,numero_nota.ilike.%${searchTerm}%`);
      }
      if (selectedStore?.id) {
        query = query.eq('loja_id', selectedStore.id);
      }
      if (dfStart) {
        query = query.gte(dateFilterType, dateFilterType === 'created_at' ? dfStart : dfStart);
      }
      if (dfEnd) {
        if (dateFilterType === 'created_at') {
          query = query.lte('created_at', dfEnd + 'T23:59:59');
        } else {
          query = query.lte(dateFilterType, dfEnd);
        }
      }
      if (statusFilter !== 'all') {
        query = query.eq('status', statusFilter);
      }

      // Ordenação por data de lançamento no sistema (created_at) — mais recentes acima
      query = query.order('created_at', { ascending: sortAsc });

      const { data, error } = await query;
      if (error) throw error;
      const results = (data || []) as any[];
      setNotas(results);

      // Carrega status financeiro das NFs carregadas
      const ids = results.map((n) => n.id).filter((id): id is number => typeof id === 'number');
      if (ids.length > 0) {
        const { data: pagData } = await supabase
          .from('contas_pagar_receber')
          .select('nota_fiscal_id, status, data_pagamento')
          .in('nota_fiscal_id', ids);
        const map: Record<number, { status: string | null; data_pagamento: string | null }> = {};
        (pagData || []).forEach((p: any) => {
          if (p.nota_fiscal_id != null) {
            map[p.nota_fiscal_id] = { status: p.status, data_pagamento: p.data_pagamento };
          }
        });
        setPaymentStatusByNotaId(map);
      } else {
        setPaymentStatusByNotaId({});
      }
      return results.length;
    }, telemetryAttrs);

    const durationMs = Math.round(performance.now() - startTime);
    wideInfo('financeiro.nf.lista_carregada', 'Lista de notas fiscais carregada com sucesso', enrichWideEvent('notas-fiscais', {
      result_count: resultCount,
      duration_ms: durationMs,
      'nota.periodo': `${dfStart}_${dfEnd}`,
      'nota.filtro_tipo': dateFilterType,
      'nota.filtro': statusFilter,
      'nota.unidade': selectedStore?.name ?? 'todas',
    }));
    recordOperationDuration('financeiro.nf.lista', durationMs);
  } catch (error) {
    const durationMs = Math.round(performance.now() - startTime);
    wideError('financeiro.nf.lista_erro', 'Erro ao carregar lista de notas fiscais', enrichWideEvent('notas-fiscais', {
      'error.message': error instanceof Error ? error.message : String(error),
      duration_ms: durationMs,
      'nota.periodo': `${dfStart}_${dfEnd}`,
      'nota.filtro_tipo': dateFilterType,
      'nota.filtro': statusFilter,
      'nota.unidade': selectedStore?.name ?? 'todas',
    }));
    recordError('financeiro_nf_lista', 'carregar');
    handleError(error, { domain: 'notas-fiscais', operation: 'carregarNotas', showToast: false });
    toast.error('Erro ao carregar notas fiscais');
  }
};

const handleFileSelect = (file: File | null) => {
  setSelectedFile(file);
  setSelectedFiles(file ? [file] : []);
  if (!file) {
    setExtractedData(null);
    setEditingData(null);
  }
};

const handleFilesSelect = (files: File[]) => {
  setSelectedFiles(files);
  setSelectedFile(files[0] || null);
};

const handleManualSave = async (data: any) => {
  setEditingData(data);
  await saveNota();
};

// Separar salvamento manual para garantir que o state editingData esteja atualizado
// Mas como a modal passa o data no onSave, podemos usar esse data diretamente ou setar o state e depois salvar.
// Vou ajustar o saveNota para aceitar um argumento opcional de dados, ou usar o editingData que já setamos.

// Refazendo saveNota para ser mais robusto e aceitar dados diretamente se passado
// ou usar editingData se nao passado.
const saveNota = async (dataToSave = editingData, options?: { lojaIdOverride?: number | null; formaPagamento?: string; creditCardId?: number | null }) => {
  if (isSaving) return;
  if (!dataToSave) return;

  // GUARD: Notas de transferência NUNCA podem ser salvas como nota fiscal
  if (isTransferNote(dataToSave)) {
    toast.error('Esta nota é de transferência interna (Momma Doces). Use a aba "Notas de Transferência" para lançá-la.');
    return;
  }

  // Atualiza state para garantir consistencia se precisarmos
  setEditingData(dataToSave);

  setIsSaving(true);
  const startTime = performance.now();
  try {
    // Verificação rápida de duplicidade
    if (dataToSave?.numero_nota && dataToSave?.fornecedor) {
      // Se estamos editando uma nota EXISTENTE (tem ID), ignoramos ela mesma na busca de duplicidade?
      // O código original não tratava edição vs criação explicitamente no saveNota para duplicidade, 
      // mas o 'handleEditNota' apenas preenchia o editingData.
      // Se 'selectedNota' existe, é uma edição.

      // TODO: Melhorar lógica de edição vs criação. Por enquanto mantendo compatível com original.
