2	import { describe, it, expect, vi, beforeEach } from 'vitest';
3	
4	import { supabase } from '@/integrations/supabase/client';
5	
6	// Variável para controlar permissões nos testes
7	let mockCanViewNotasFiscais = true;
8	
9	// ── Mocks needed for page import ────────────────────────────────────────────
10	vi.mock('sonner', () => ({
11	    toast: Object.assign(vi.fn(), { error: vi.fn(), success: vi.fn() }),
12	}));
13	
14	vi.mock('@/shared/hooks/use-mobile', () => ({
15	    useIsMobile: () => false,
16	    useHasCamera: () => false,
17	}));
18	
19	// Helper para criar mock encadeado do Supabase.
20	// `then` é implementado como thenable síncrono (sem microtask) para evitar
21	// act() warnings em testes que não usam waitFor.
22	const createSupabaseMock = (returnData: any[] = [], returnError: any = null) => {
23	  const result = { data: returnData, error: returnError };
24	  const mockChain: any = {
25	    select: vi.fn().mockReturnThis(),
26	    eq: vi.fn().mockReturnThis(),
27	    neq: vi.fn().mockReturnThis(),
28	    not: vi.fn().mockReturnThis(),
29	    in: vi.fn().mockReturnThis(),
30	    gte: vi.fn().mockReturnThis(),
31	    lte: vi.fn().mockReturnThis(),
32	    or: vi.fn().mockReturnThis(),
33	    ilike: vi.fn().mockReturnThis(),
34	    order: vi.fn().mockReturnThis(),
35	    limit: vi.fn().mockReturnThis(),
36	    range: vi.fn().mockReturnThis(),
37	    single: vi.fn().mockResolvedValue({ data: returnData[0] ?? null, error: returnError }),
38	    maybeSingle: vi.fn().mockResolvedValue({ data: returnData[0] ?? null, error: returnError }),
39	    // then síncrono: chama o resolve imediatamente, retorna Promise para await funcionar
40	    then: vi.fn().mockImplementation((resolve: any, reject?: any) => {
41	      try {
42	        const resolved = resolve(result);
43	        return Promise.resolve(resolved);
44	      } catch (e) {
45	        return reject ? Promise.reject(e).catch(reject) : Promise.reject(e);
46	      }
47	    }),
48	    catch: vi.fn().mockImplementation((_reject: any) => Promise.resolve(result)),
49	    finally: vi.fn().mockImplementation((cb: any) => { cb(); return Promise.resolve(result); }),
50	  };
51	  return mockChain;
52	};
53	
54	// Mocks globais adicionais
55	vi.mock('@/integrations/supabase/client', () => ({
56	  supabase: {
57	    from: vi.fn(() => createSupabaseMock()),
58	    auth: {
59	      getSession: vi.fn().mockResolvedValue({ data: { session: { user: { id: 'test-user' } } }, error: null }),
60	    },
61	  },
62	}));
63	
64	vi.mock('@/shared/ui/button', () => ({
65	  Button: ({ children, ...props }: any) => <button {...props}>{children}</button>,
66	  buttonVariants: vi.fn(),
67	}));
68	
69	vi.mock('@/shared/ui/card', () => ({
70	  Card: ({ children }: any) => <div>{children}</div>,
71	  CardContent: ({ children }: any) => <div>{children}</div>,
72	  CardHeader: ({ children }: any) => <div>{children}</div>,
73	  CardTitle: ({ children }: any) => <div>{children}</div>,
74	  CardDescription: ({ children }: any) => <div>{children}</div>,
75	}));
76	
77	vi.mock('@/shared/ui/glass-card', () => ({
78	  GlassCard: ({ children }: any) => <div>{children}</div>,
79	}));
