import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach } from 'vitest';

import { supabase } from '@/integrations/supabase/client';

// Variável para controlar permissões nos testes
let mockCanViewNotasFiscais = true;

// ── Mocks needed for page import ────────────────────────────────────────────
vi.mock('sonner', () => ({
    toast: Object.assign(vi.fn(), { error: vi.fn(), success: vi.fn() }),
}));

vi.mock('@/shared/hooks/use-mobile', () => ({
    useIsMobile: () => false,
    useHasCamera: () => false,
}));

// Helper para criar mock encadeado do Supabase.
// `then` é implementado como thenable síncrono (sem microtask) para evitar
// act() warnings em testes que não usam waitFor.
const createSupabaseMock = (returnData: any[] = [], returnError: any = null) => {
  const result = { data: returnData, error: returnError };
  const mockChain: any = {
    select: vi.fn().mockReturnThis(),
    eq: vi.fn().mockReturnThis(),
    neq: vi.fn().mockReturnThis(),
    not: vi.fn().mockReturnThis(),
    in: vi.fn().mockReturnThis(),
    gte: vi.fn().mockReturnThis(),
    lte: vi.fn().mockReturnThis(),
    or: vi.fn().mockReturnThis(),
    ilike: vi.fn().mockReturnThis(),
    order: vi.fn().mockReturnThis(),
    limit: vi.fn().mockReturnThis(),
    range: vi.fn().mockReturnThis(),
    single: vi.fn().mockResolvedValue({ data: returnData[0] ?? null, error: returnError }),
    maybeSingle: vi.fn().mockResolvedValue({ data: returnData[0] ?? null, error: returnError }),
    // then síncrono: chama o resolve imediatamente, retorna Promise para await funcionar
    then: vi.fn().mockImplementation((resolve: any, reject?: any) => {
      try {
        const resolved = resolve(result);
        return Promise.resolve(resolved);
      } catch (e) {
        return reject ? Promise.reject(e).catch(reject) : Promise.reject(e);
      }
    }),
    catch: vi.fn().mockImplementation((_reject: any) => Promise.resolve(result)),
    finally: vi.fn().mockImplementation((cb: any) => { cb(); return Promise.resolve(result); }),
  };
  return mockChain;
};

// Mocks globais adicionais
vi.mock('@/integrations/supabase/client', () => ({
  supabase: {
    from: vi.fn(() => createSupabaseMock()),
    auth: {
      getSession: vi.fn().mockResolvedValue({ data: { session: { user: { id: 'test-user' } } }, error: null }),
    },
  },
}));

vi.mock('@/shared/ui/button', () => ({
  Button: ({ children, ...props }: any) => <button {...props}>{children}</button>,
  buttonVariants: vi.fn(),
}));

vi.mock('@/shared/ui/card', () => ({
  Card: ({ children }: any) => <div>{children}</div>,
  CardContent: ({ children }: any) => <div>{children}</div>,
  CardHeader: ({ children }: any) => <div>{children}</div>,
  CardTitle: ({ children }: any) => <div>{children}</div>,
  CardDescription: ({ children }: any) => <div>{children}</div>,
}));

vi.mock('@/shared/ui/glass-card', () => ({
  GlassCard: ({ children }: any) => <div>{children}</div>,
}));

import '@testing-library/jest-dom';
import { vi } from 'vitest';

// Mock de window.matchMedia para jsdom (usado por useIsMobile e componentes responsivos)
Object.defineProperty(window, 'matchMedia', {
  writable: true,
  value: vi.fn().mockImplementation((query: string) => ({
    matches: false,
    media: query,
    onchange: null,
    addListener: vi.fn(), // deprecated
    removeListener: vi.fn(), // deprecated
    addEventListener: vi.fn(),
    removeEventListener: vi.fn(),
    dispatchEvent: vi.fn(),
  })),
});

// Mock do ResizeObserver
global.ResizeObserver = class {
  observe() {}
  unobserve() {}
  disconnect() {}
};

// Mock global do cliente Supabase para todos os testes unitários
// Chainable builder: cada método retorna o próprio builder, permitindo qualquer
// combinação de .from().select().eq().single() etc.
vi.mock('@/integrations/supabase/client', () => {
  const builder: Record<string, any> = {};
  const chainMethods = [
    'from', 'select', 'insert', 'update', 'upsert', 'delete',
    'eq', 'neq', 'gt', 'gte', 'lt', 'lte', 'like', 'ilike',
    'is', 'in', 'not', 'or', 'filter', 'match',
    'order', 'limit', 'range', 'single', 'maybeSingle',
    'csv', 'returns',
  ];
  for (const m of chainMethods) {
    builder[m] = vi.fn().mockReturnValue(builder);
  }
  builder.then = vi.fn((resolve: any) => resolve({ data: [], error: null }));
  return {
    supabase: {
      ...builder,
      rpc: vi.fn().mockResolvedValue({ data: [], error: null }),
      auth: {
        getUser: vi.fn(),
        signInWithPassword: vi.fn(),
        signOut: vi.fn(),
        getSession: vi.fn().mockResolvedValue({ data: { session: null }, error: null }),
        refreshSession: vi.fn().mockResolvedValue({ data: { session: null }, error: null }),
        onAuthStateChange: vi.fn(() => ({ data: { subscription: { unsubscribe: vi.fn() } } })),
      },
      channel: vi.fn().mockReturnValue({
        on: vi.fn().mockReturnThis(),
        subscribe: vi.fn(),
      }),
      removeChannel: vi.fn(),
    },
    SESSION_UNAUTHORIZED_EVENT: 'supabase:unauthorized',
  };
});

// Mock global do useTelemetryAttrs — hook de observabilidade que depende de
// useLocation, useAuth e useStore. Retorna objeto vazio em testes.
vi.mock('@/shared/lib/telemetry/useTelemetryAttrs', () => ({
  useTelemetryAttrs: () => ({}),
}));

// Mock global do MiaContext — evita que MiaProvider precise de StoreProvider
// real. Testes específicos de MIA fazem override local.
vi.mock('@/shared/contexts/MiaContext', () => ({
  MiaProvider: ({ children }: any) => children,
  useMia: () => ({
    messages: [],
    isStreaming: false,
    streamingStatus: '',
    sendMessage: vi.fn(),
    clearConversation: vi.fn(),
    conversations: [],
    activeConversationId: null,
    setActiveConversationId: vi.fn(),
    createConversation: vi.fn(),
    deleteConversation: vi.fn(),
    renameConversation: vi.fn(),
    registerActions: vi.fn(),
    unregisterActions: vi.fn(),
  }),
  useMiaGlassBoxContext: () => ({
    miaModeEnabled: false,
    toggleMiaMode: vi.fn(),
    setMiaModeEnabled: vi.fn(),
    paneSize: 33,
    setPaneSize: vi.fn(),
    autonomyMode: 'assistido',
    setAutonomyMode: vi.fn(),
    currentPageModel: null,
    setCurrentPageModel: vi.fn(),
    watchLog: [],
    addWatchLogEntry: vi.fn(),

