import { render, screen, fireEvent } from '@testing-library/react';
import { describe, it, expect, vi } from 'vitest';

// ── Mocks ────────────────────────────────────────────────────────────────────
vi.mock('sonner', () => ({
    toast: Object.assign(vi.fn(), { error: vi.fn(), success: vi.fn() }),
}));

vi.mock('@/shared/hooks/use-mobile', () => ({
    useIsMobile: () => false,
}));

// ── Extracted helper logic ───────────────────────────────────────────────────

// updateItem: auto-calculates subtotal & total
const updateItem = (
    data: any,
    index: number,
    field: string,
    value: any,
) => {
    const newItens = [...(data.itens || [])];
    const currentItem = { ...newItens[index], [field]: value };

    if (field === 'quantidade' || field === 'valor_unitario') {
        const qty =
            field === 'quantidade'
                ? parseFloat(value)
                : parseFloat(currentItem.quantidade);
        const price =
            field === 'valor_unitario'
                ? parseFloat(value)
                : parseFloat(currentItem.valor_unitario);
        if (!isNaN(qty) && !isNaN(price)) {
            currentItem.subtotal = parseFloat((qty * price).toFixed(2));
        }
    }

    newItens[index] = currentItem;
    const newTotal = newItens.reduce(
        (sum: number, item: any) => sum + (parseFloat(item.subtotal) || 0),
        0,
    );
    return { ...data, itens: newItens, valor_total: newTotal };
};

const addItem = (data: any) => ({
    ...data,
    itens: [
        ...(data.itens || []),
        { nome_produto: '', quantidade: 0, valor_unitario: null, subtotal: null, categoria: '' },
    ],
});

const removeItem = (data: any, index: number) => {
    const newItens = [...(data.itens || [])];
    newItens.splice(index, 1);
    const newTotal = newItens.reduce(
        (sum: number, item: any) => sum + (parseFloat(item.subtotal) || 0),
        0,
    );
    return { ...data, itens: newItens, valor_total: newTotal };
};

// ── Helper tests ────────────────────────────────────────────────────────────

describe('ManualInvoiceModal — updateItem logic', () => {
    const baseData = {
        itens: [
            { nome_produto: 'Farinha', quantidade: 10, valor_unitario: 5, subtotal: 50 },
        ],
        valor_total: 50,
    };

    it('auto-calculates subtotal when quantidade changes', () => {
        const result = updateItem(baseData, 0, 'quantidade', '20');
        expect(result.itens[0].subtotal).toBeCloseTo(100, 2); // 20 * 5
        expect(result.valor_total).toBeCloseTo(100, 2);
    });

